const lines = [];
let line;
while ((line = readLine()) !== null) lines.push(line);
const tok = lines.join(' ').split(/\s+/).filter(s => s.length).map(Number);
const n = tok[0];
const pts = [];
for (let i = 0; i < n; i++) pts.push([tok[1 + 2 * i], tok[2 + 2 * i]]);
pts.sort((a, b) => a[0] - b[0] || a[1] - b[1]);
function d2(a, b) { const dx = a[0] - b[0], dy = a[1] - b[1]; return dx * dx + dy * dy; }
function closest(lo, hi) {
  if (hi - lo <= 3) {
    let best = Infinity;
    for (let i = lo; i < hi; i++) for (let j = i + 1; j < hi; j++) best = Math.min(best, d2(pts[i], pts[j]));
    return best;
  }
  const mid = (lo + hi) >> 1, midx = pts[mid][0];
  let best = Math.min(closest(lo, mid), closest(mid, hi));
  const strip = [];
  for (let i = lo; i < hi; i++) { const dx = pts[i][0] - midx; if (dx * dx < best) strip.push(pts[i]); }
  strip.sort((a, b) => a[1] - b[1]);
  for (let i = 0; i < strip.length; i++) {
    for (let j = i + 1; j < strip.length; j++) {
      const dy = strip[j][1] - strip[i][1];
      if (dy * dy >= best) break;
      best = Math.min(best, d2(strip[i], strip[j]));
    }
  }
  return best;
}
