import java.io.*;
import java.util.*;

public class Main {
    static long[][] pts;

    static long d2(long[] a, long[] b) {
        long dx = a[0] - b[0], dy = a[1] - b[1];
        return dx * dx + dy * dy;
    }

    static long closest(int lo, int hi) {
        if (hi - lo <= 3) {
            long best = Long.MAX_VALUE;
            for (int i = lo; i < hi; i++)
                for (int j = i + 1; j < hi; j++) best = Math.min(best, d2(pts[i], pts[j]));
            return best;
        }
        int mid = (lo + hi) / 2;
        long midx = pts[mid][0];
        long best = Math.min(closest(lo, mid), closest(mid, hi));
        ArrayList<long[]> strip = new ArrayList<>();
        for (int i = lo; i < hi; i++) {
            long dx = pts[i][0] - midx;
            if (dx * dx < best) strip.add(pts[i]);
        }
        strip.sort((a, b) -> Long.compare(a[1], b[1]));
        for (int i = 0; i < strip.size(); i++) {
            for (int j = i + 1; j < strip.size(); j++) {
                long dy = strip.get(j)[1] - strip.get(i)[1];
                if (dy * dy >= best) break;
                best = Math.min(best, d2(strip.get(i), strip.get(j)));
            }
        }
        return best;
    }

    public static void main(String[] args) throws IOException {
        StreamTokenizer in = new StreamTokenizer(new BufferedInputStream(System.in));
        in.nextToken();
        int n = (int) in.nval;
        pts = new long[n][2];
        for (int i = 0; i < n; i++) {
            in.nextToken(); pts[i][0] = (long) in.nval;
            in.nextToken(); pts[i][1] = (long) in.nval;
        }
        Arrays.sort(pts, (a, b) -> a[0] != b[0] ? Long.compare(a[0], b[0]) : Long.compare(a[1], b[1]));
        System.out.println(closest(0, n));
    }
}

