#include <bits/stdc++.h>
using namespace std;
typedef long long ll;
typedef pair<ll,ll> P;
vector<P> pts;

ll d2(const P& a, const P& b) {
    ll dx = a.first - b.first, dy = a.second - b.second;
    return dx * dx + dy * dy;
}
ll closest(int lo, int hi) {
    if (hi - lo <= 3) {
        ll best = LLONG_MAX;
        for (int i = lo; i < hi; i++)
            for (int j = i + 1; j < hi; j++) best = min(best, d2(pts[i], pts[j]));
        return best;
    }
    int mid = (lo + hi) / 2;
    ll midx = pts[mid].first;
    ll best = min(closest(lo, mid), closest(mid, hi));
    vector<P> strip;
    for (int i = lo; i < hi; i++) {
        ll dx = pts[i].first - midx;
        if (dx * dx < best) strip.push_back(pts[i]);
    }
    sort(strip.begin(), strip.end(), [](const P& a, const P& b) { return a.second < b.second; });
    for (size_t i = 0; i < strip.size(); i++) {
        for (size_t j = i + 1; j < strip.size(); j++) {
            ll dy = strip[j].second - strip[i].second;
            if (dy * dy >= best) break;
            best = min(best, d2(strip[i], strip[j]));
        }
    }
    return best;
}
int main() {
    int n;
    scanf("%d", &n);
    pts.resize(n);
    for (auto& p : pts) scanf("%lld %lld", &p.first, &p.second);
    sort(pts.begin(), pts.end());
    printf("%lld\n", closest(0, n));
    return 0;
}
